int F(int n){
    if(n == 0 || n == 1) return n;
    return F(n - 1) + F(n - 2);
}

int C(int n, int k){
    if(n == k || k == 0) return 1;
    return C(n - 1, k - 1) + C(n - 1, k);
}

void dec_to_bin(long long n){
    if(n < 2){ printf("%lld", n); }
    else{
        dec_to_bin(n / 2);
        printf("%lld", n % 2);
    }
}

void dec_to_hex(long long n){
    if(n < 16){
        printf("%c", n < 10 ? (char)('0' + n) : (char)(n + 55));
    } else {
        dec_to_hex(n / 16);
        int r = n % 16;
        printf("%c", r < 10 ? (char)('0' + r) : (char)(r + 55));
    }
}

int D(long long n){ return n < 10 ? 1 : 1 + D(n / 10); }

int S(long long n){ return n < 10 ? n : n % 10 + S(n / 10); }
// D(28282828)=8   S(28282828)=40

int SumEven(long long n){
    if(n < 10) return n % 2 ? 0 : n;
    return (n % 2 ? 0 : n % 10) + SumEven(n / 10);
}

int MaxDigit(long long n){
    if(n < 10) return n;
    int tmp = MaxDigit(n / 10);
    return n % 10 > tmp ? n % 10 : tmp;
}

int S1(int n){ return n==1 ? 1 : n + S1(n-1); }
int S2(int n){ return n==1 ? 1 : n*n + S2(n-1); }
double S3(int n){ return n==1 ? 1 : (double)1/n + S3(n-1); }

int even_sum(int a[], int n){
    if(n == 0) return 0;
    if(a[n-1] % 2 == 0) return a[n-1] + even_sum(a, n-1);
    return even_sum(a, n-1);
}
// {1,2,3,4,5,6} -> 12

bool doixung(int a[], int left, int right){
    if(left > right) return true;
    if(a[left] != a[right]) return false;
    return doixung(a, left + 1, right - 1);
}

void trai_phai(int a[], int n){
    if(n > 0){ trai_phai(a, n-1); printf("%d ", a[n-1]); }
}

void phai_trai(int a[], int n){
    if(n > 0){ printf("%d ", a[n-1]); phai_trai(a, n-1); }
}
